1	// BtTransfer.js —— 蓝牙动态资料集接收器（v1.16.46 主人需求）
2	// ─────────────────────────────────────────────────────────────────
3	// 【触发逻辑】应用级全局生效：app.ux onCreate 调 initBtReceiver() 挂 interconnect
4	// 监听，任何界面收到传输都会触发（不是特定页面触发）。
5	//
6	// 【传输协议】（手机 App / ble_tools → 手环 interconnect onmessage，JSON 文本帧）：
7	//   {t:'ds-begin', ds:'<集目录名>', name:'<显示名>', total:<文件数>}
8	//   {t:'ds-chunk', ds, f:'<文件名>', i:<分片号>, last:0|1, data:'<文本片段>'}   // 大文件分片拼装
9	//   {t:'ds-end',   ds}                                                        // 全部就绪 → 触发加载
10	// 引擎所需完整文件集：meta.txt + map_N.txt + detail_N.txt + block_0.txt（见 docs/资料拆分指南.md）。
11	//
12	// 【落盘位置】internal://files/datasets/<ds>/ —— @system.file 沙箱，运行时可写可读；
13	// /common/ 是 rpk 打包只读资源目录，运行时不可写，所以蓝牙集必须落沙箱。
14	// 引擎按 basePath 读文件，沙箱 URI 直接可用（DatasetManager ds.baseUri 支持）。
15	//
16	// 【加载触发】ds-end 收齐 → registerDynamicDataset 注册（全局生效，搜索/详情立即可达）
17	// → router.replace('/pages/loading?source=bt&ds=<ds>') → loading 页【只】对该集
18	// 建缓存（_lazyInit + _ensureMap + _ensureChunk），不跑历史集 init、不跑全量预热。
19	'use strict'
20	
21	var receiving = null // { ds, name, total, files: {fname: {chunks:{i:data}, got, last}} }
22	
23	// v1.16.66 传输状态（主人需求：专门蓝牙传输界面）：
24	// 供 pages/btransfer 轮询显示——phase: idle/receiving/saving/done/error/aborted
25	var transfer = { phase: 'idle', ds: '', dsId: '', name: '', total: 0, done: 0, currentFile: '', error: '' }
26	function getTransferState() { return transfer }
27	function _resetTransfer() { transfer = { phase: 'idle', ds: '', dsId: '', name: '', total: 0, done: 0, currentFile: '', error: '' } }
28	var registered = false
29	
30	function _log(msg, level) {
31	  console.log('[BT-DS] ' + msg)
32	  try { if (typeof global !== 'undefined' && global.addRuntimeLog) global.addRuntimeLog('[蓝牙资料] ' + msg, level || 'info') } catch (e) {}
33	}
34	
35	function baseDir(ds) {
36	  return 'internal://files/datasets/' + ds + '/'
37	}
38	
39	// 单文件落盘（分片按序拼装后一次性 writeText）
40	function flushFile(ds, fname, parts) {
41	  return new Promise(function(resolve, reject) {
42	    try {
43	      var file = require('@system.file')
44	      var dir = baseDir(ds)
45	      file.mkdir({ uri: dir, recursive: true, success: function() {
46	        var body = ''
47	        var i = 0
48	        while (parts[i] !== undefined) { body += parts[i]; i++ }
49	        file.writeText({
50	          uri: dir + fname,
51	          text: body,
52	          success: function() { resolve() },
53	          fail: function(err, code) { reject(new Error('writeText fail code=' + code)) }
54	        })
55	      }, fail: function(err, code) { reject(new Error('mkdir fail code=' + code)) } })
56	    } catch (e) { reject(e) }
57	  })
58	}
59	
60	// 处理一条 interconnect 消息（JSON 帧，见头部协议）
61	// ⚠️ 消息形态双兼容（审查修复）：官方互联层可能以 {data:'<json>'} 包装投递
62	//（AssistantEngine 即按 data.data 解析），也可能直接投递裸字符串/对象——
63	// 两种形态都兜住，真机联调无需再改。
64	function handleMessage(data) {
65	  var payload = data
66	  if (data && typeof data === 'object' && typeof data.data === 'string') payload = data.data
67	  var msg
68	  try { msg = typeof payload === 'string' ? JSON.parse(payload) : payload } catch (e) { return }
69	  if (!msg || !msg.t) return
70	
71	  if (msg.t === 'ds-begin') {
72	    // v1.16.120：尊重「设置 → 蓝牙接收」开关（此前只写不读 = 假开关，审查报告 #2）。
73	    // undefined 视为开启（保持默认行为不变）；关闭时直接忽略，不跳传输页。
74	    var _btAllowed = true
75	    try { if (typeof global !== 'undefined' && global.bluetoothReceive === false) _btAllowed = false } catch (e) {}
76	    if (!_btAllowed) { _log('蓝牙接收已关闭，忽略 ds-begin: ' + msg.ds); return }
77	    receiving = { ds: String(msg.ds || ''), name: String(msg.name || msg.ds || ''), total: msg.total || 0, files: {} }
78	    // 进入专门传输界面（无退出入口，只能手机端停止或传完）
79	    transfer = { phase: 'receiving', ds: receiving.ds, dsId: '', name: receiving.name, total: receiving.total, done: 0, currentFile: '', error: '' }
80	    try { require('@system.router').replace({ uri: '/pages/btransfer' }) } catch (e) {}
81	    _log('开始接收资料集: ' + receiving.ds + '（' + receiving.total + ' 个文件）')
82	  } else if (msg.t === 'ds-chunk' && receiving && receiving.ds === String(msg.ds || '')) {
83	    var fname = String(msg.f || '')
84	    if (!fname) return
85	    var rec = receiving.files[fname] || (receiving.files[fname] = { chunks: {}, got: 0, last: false })
86	    var idx = msg.i || 0
87	    if (rec.chunks[idx] === undefined) { rec.chunks[idx] = String(msg.data || ''); rec.got++ }
88	    transfer.currentFile = fname
89	    if (msg.last && !rec.last) {
90	      rec.last = true
91	      transfer.done++
92	      // 流式：收齐即落盘（审查中#7），从内存释放
93	      var dsNow = receiving.ds
94	      finalizeFile(dsNow, fname, rec).then(function(ok) {
95	        if (receiving && receiving.ds === dsNow) delete receiving.files[fname]
96	      })
97	    }
98	  } else if (msg.t === 'ds-file' && receiving && receiving.ds === String(msg.ds || '')) {
99	    // 单帧整文件（小文件可不切片）。空文件名防护（审查修复）：空名会让后续
100	    // flushFile 对目录本身 writeText → 整批落盘失败
101	    var fname2 = String(msg.f || '')
102	    if (!fname2) return
103	    var rec2 = receiving.files[fname2] || (receiving.files[fname2] = { chunks: {}, got: 0, last: false })
104	    if (!rec2.last) {
105	      rec2.chunks[0] = String(msg.data || '')
106	      rec2.got = 1
107	      rec2.last = true
108	      transfer.done++
109	      transfer.currentFile = fname2
110	      var dsNow2 = receiving.ds
111	      finalizeFile(dsNow2, fname2, rec2).then(function(ok) {
112	        if (receiving && receiving.ds === dsNow2) delete receiving.files[fname2]
113	      })
114	    }
115	  } else if (msg.t === 'ds-abort') {
116	    // 手机端主动停止（主人定案：传输中唯一退出途径）——回首页
117	    _log('手机端已停止传输', 'warn')
118	    receiving = null
119	    _resetTransfer()
120	    transfer.phase = 'aborted'
121	    try { require('@system.router').replace({ uri: '/pages/index' }) } catch (e) {}
122	  } else if (msg.t === 'ds-end' && receiving && receiving.ds === String(msg.ds || '')) {
123	    // v1.16.73 流式落盘：文件在收齐时已逐个落盘——这里只做清单校验 + 注册
124	    var ds = receiving.ds
125	    var name = receiving.name
126	    var files = receiving.files
127	    var declared = receiving.total || 0
128	    receiving = null
129	    var names = Object.keys(files)
130	    // 未落盘的残留文件（finalizeFile 失败/未触发的）在此补落
131	    var chain = Promise.resolve()
132	    names.forEach(function(fn) {
133	      var rec0 = files[fn]
134	      if (rec0.chunks && rec0.got > 0) {
135	        chain = chain.then(function() { return finalizeFile(ds, fn, rec0) })
136	      }
137	    })
138	    chain.then(function(okAll) {
139	      if (declared > 0 && names.length !== declared) {
140	        transfer.phase = 'error'
141	        transfer.error = '文件数不符(声明' + declared + '/实收' + names.length + ')'
142	        _log('文件数不符: 声明' + declared + '/实收' + names.length, 'error')
143	        return
144	      }
145	      _log('全部落盘完成: internal://files/datasets/' + ds + '/', 'success')
146	      var DatasetManager = require('./DatasetManager.js')
147	      var dsObj = DatasetManager.registerDynamicDataset({ dirName: ds, name: name })
148	      transfer.phase = 'done'
149	      transfer.dsId = String(dsObj.id)
150	      transfer.done = names.length
151	    }).catch(function(e) {
152	      transfer.phase = 'error'
153	      transfer.error = '保存失败：' + (e && e.message ? e.message : '未知')
154	      _log('落盘失败: ' + (e && e.message), 'error')
155	    })
156	  }
157	}
158	
159	// 单文件收齐即落盘并从内存释放（流式：审查中#7——原实现全部文件驻留内存到
160	// ds-end 才落盘，大资料集直接 OOM）。校验该文件分片连续（0..got-1 齐全）。
161	function finalizeFile(ds, fname, rec) {
162	  var missing = -1
163	  for (var ci = 0; ci < rec.got; ci++) {
164	    if (rec.chunks[ci] === undefined) { missing = ci; break }
165	  }
166	  if (missing !== -1) {
167	    _log('文件 ' + fname + ' 缺片#' + missing + '，拒绝落盘（请重新发送）', 'error')
168	    transfer.phase = 'error'
169	    transfer.error = '资料 ' + fname + ' 传输不完整（缺片），请在手机端重发'
170	    return Promise.resolve(false)
171	  }
172	  return flushFile(ds, fname, rec.chunks).then(function() {
173	    _log('文件落盘: ' + fname + '（' + rec.got + ' 片）', 'success')
174	    return true
175	  }).catch(function(e) {
176	    _log('文件 ' + fname + ' 落盘失败: ' + (e && e.message), 'error')
177	    transfer.phase = 'error'
178	    transfer.error = '保存失败：' + fname
179	    return false
180	  })
181	}
182	
183	// 应用级监听（app.ux onCreate 调一次；重复调用幂等）
184	// ⚠️ 包装链（审查修复）：AssistantEngine 也在这条通道上设 conn.onmessage（语音/AI 真链路），
185	// 直接赋值会互相覆盖（后设者赢，另一模块静默失效）。此处保留原 handler 并转发，
186	// 无论设置顺序如何，两个模块都能收到消息。
187	function initBtReceiver() {
188	  if (registered) return false
189	  try {
190	    var interconnect = require('@system.interconnect')
191	    var conn = interconnect.instance()
192	    var prevHandler = conn.onmessage
193	    conn.onmessage = function(data) {
194	      try { handleMessage(data) } catch (e) { _log('消息处理异常: ' + (e && e.message), 'error') }
195	      // 转发给此前的监听者（如 AssistantEngine 的语音/AI 应答处理）
196	      if (typeof prevHandler === 'function') {
197	        try { prevHandler(data) } catch (e) {}
198	      }
199	    }
200	    registered = true
201	    _log('蓝牙资料接收器已就绪（应用级全局监听）', 'success')
202	    return true
203	  } catch (e) {
204	    _log('interconnect 不可用，接收器未启动（模拟器/无蓝牙环境自动静默）', 'warn')
205	    return false
206	  }
207	}
208	
209	module.exports = { initBtReceiver: initBtReceiver, handleMessage: handleMessage, baseDir: baseDir, getTransferState: getTransferState }
