1	// 跨集详情读取：gid → 集 → detail 分片按 meta.fields 列序拆字段
2	// （detail.ux 的历史集读取逻辑硬编码 /common 路径与 v4 列序，无法吃资料集格式——此处统一适配）
3	// ⚠️ 必须显式 import：各 JS 模块作用域独立，DATASETS/decodeGlobalId/ensureEngine 不会凭空可见
4	import { DATASETS, ensureEngine, decodeGlobalId } from './DatasetManager.js'
5	
6	var FIELD_NAME_MAP = { source: '出处', content: '正文', keywords: '关键词', author: '作者',
7	  // 历史集（v1.16.61 统一引擎路径后，历史集字段经此映射显示中文名）
8	  cause: '原因/背景', impact: '影响/做法' }
9	
10	function _readText(uri) {
11	  // file 用函数内 require（与引擎一致——顶层静态 import 原生模块在快应用互操作下不可靠）
12	  var file = require('@system.file')
13	  return new Promise(function(resolve) {
14	    file.readText({
15	      uri: uri,
16	      success: function(res) { resolve(res.text || '') },
17	      fail: function() { resolve('') }
18	    })
19	  })
20	}
21	
22	// fields 声明在 meta.json；meta.txt 是引擎吃的 v4 兼容壳（无 fields 键）
23	// 兼容两种声明：字符串数组 ["source","content"] / 对象数组 [{name, position}]
24	async function _loadMeta(eng) {
25	  var raw = await _readText(eng.basePath + 'meta.json')
26	  var metaObj = {}
27	  try { metaObj = JSON.parse(raw) } catch (e) { metaObj = {} }
28	  if (!metaObj.fields) {
29	    // 历史集特例（v1.16.63；v1.16.122 后数据已归入 datasets/history/，声明文件同目录）：
30	    // meta.txt 无 fields 时读 meta.json 拿字段名
31	    if (eng.basePath === '/common/datasets/history/') {
32	      raw = await _readText('/common/datasets/history/meta.json')
33	      try { metaObj = JSON.parse(raw) } catch (e1) { metaObj = {} }
34	    }
35	  }
36	  if (!metaObj.fields) {
37	    raw = await _readText(eng.basePath + 'meta.txt')
38	    try { metaObj = JSON.parse(raw) } catch (e2) { metaObj = {} }
39	  }
40	  // 历史集最终兜底：物化列序就是 cause/impact（v1.16.63）
41	  var isHistory = (eng.basePath === '/common/datasets/history/')
42	  if (!metaObj.fields && isHistory) {
43	    metaObj.fields = { detail: ['cause', 'impact'] }
44	  }
45	  var names = []
46	  var fd = (metaObj.fields && metaObj.fields.detail) || []
47	  for (var i = 0; i < fd.length; i++) {
48	    var f = fd[i]
49	    var idx = (f && f.position !== undefined) ? (f.position - 2) : i
50	    names[idx] = (typeof f === 'string') ? f : f.name
51	  }
52	  return {
53	    detailChunkSize: metaObj.detailChunkSize || (eng.detailChunkSize || 100),
54	    detFieldNames: names.length ? names : ['详情']
55	  }
56	}
57	
58	// detail 内存缓存（v1.16.61 主人指定）：看完一页清一次、最多留一个——
59	// 同一详情页的重复访问（重渲染/收藏切换）免重读文件；加载新详情时替换旧页；
60	// 退出详情页（detail.ux onDestroy）调 clearDetailCache 主动清空。
61	var _detailCache = null   // { key: gid 字符串, data: 详情对象 }
62	
63	function clearDetailCache() {
64	  _detailCache = null
65	}
66	
67	async function getDetailByGlobalId(gid) {
68	  var cacheKey = String(gid)
69	  if (_detailCache && _detailCache.key === cacheKey) {
70	    return _detailCache.data
71	  }
72	  var d = decodeGlobalId(gid)
73	  var ds = null
74	  for (var i = 0; i < DATASETS.length; i++) {
75	    if (DATASETS[i].id === d.dsId) { ds = DATASETS[i]; break }
76	  }
77	  if (!ds) return null
78	  var eng = ensureEngine(ds)
79	  var mapDoc = await eng.getDoc(d.localId)
80	
81	  var meta = await _loadMeta(eng)
82	
83	  // 读 detail 分片找 localId 行
84	  var chunkId = Math.floor(d.localId / meta.detailChunkSize)
85	  var raw = await _readText(eng.basePath + 'detail_' + chunkId + '.txt')
86	
87	  var rows = raw.split('\n')
88	  var line = null
89	  for (var ri = 0; ri < rows.length; ri++) {
90	    var cols = rows[ri].split('|')
91	    if (parseInt(cols[0], 10) === d.localId) { line = cols; break }
92	  }
93	
94	  var details = []
95	  if (line) {
96	    // detail 行：localId|关键词|字段值1|字段值2...（列 2 起按 fields.detail 顺序）
97	    for (var ci = 2; ci < line.length; ci++) {
98	      // v1.16.63 最底层兜底：meta 读取失败时也保证字段名正确（历史集列序固定 cause/impact）
99	      var rawName = meta.detFieldNames[ci - 2] ||
100	        (ds.id === 0 ? (ci === 2 ? 'cause' : 'impact') : ('详情' + (ci - 1)))
101	      var name = FIELD_NAME_MAP[rawName] || rawName
102	      // 物化时真实换行编码为字面 \n 两字符（| 是列分隔符，裸换行会断行），这里还原
103	      var value = (line[ci] || '').replace(/\\n/g, '\n')
104	      if (value) details.push({ name: name, value: value })
105	    }
106	  }
107	
108	  var result = {
109	    isDataset: true,
110	    dsName: ds.name,
111	    // v1.16.63 兜底：mapDoc 缺失时用 detail 行关键词首段当标题（保证简略卡始终渲染，
112	    // 避免详情卡上移造成『简略/详情位置反了』的视觉）
113	    title: (mapDoc && mapDoc.title) || (line && line[1] ? String(line[1]).split(/[,，]/)[0] : '') || '',
114	    // 资料集无年份语义（物化 year=0 → 引擎返回「公元元年」）：年份位显示集标签
115	    yearDisplay: ds.id !== 0 ? ds.tag : ((mapDoc && mapDoc.yearDisplay) || ds.tag || '历史'),
116	    region: (mapDoc && mapDoc.region) || ds.tag,
117	    keywords: line && line[1] ? line[1].split(',').filter(function(k) { return k }) : [],
118	    details: details
119	  }
120	  // 写入缓存（替换旧页 = 只留一个，v1.16.61 主人指定）
121	  _detailCache = { key: cacheKey, data: result }
122	  return result
123	}
124	
125	
126	export { getDetailByGlobalId, clearDetailCache }
