1	<script>
2	  // ========== 搜索引擎（全局引擎初始化，从原 splash.ux 提取到 app 生命周期）==========
3	  import { getSearchEngine } from './SearchEngine/SearchEngine.js'
4	  // 应用版本（与 src/manifest.json 的 versionName 保持同步——改版本时两处一起改）
5	  const APP_VERSION = '1.16.123'  // ⚠️ 必须与 manifest.json versionName 同步（审查第二次发现脱节：1.16.71 落后 46 版）
6	  // 发版检查项：改 manifest.json 的 versionName 时，同一提交内必须改这里（APP_VERSION 用于设置页「关于」展示）
7	  import { searchAllAsync, getItemByGlobalId, getDatasetEntries, getGroupEntries, getDatasetInfo, warmupAllCaches } from './SearchEngine/DatasetManager.js'
8	  import { initBtReceiver } from './SearchEngine/BtTransfer.js'
9	
10	  // ========== 日志系统（直接操作 storage）==========
11	  var LOG_KEY = 'app_runtime_logs'
12	  var MAX_LOGS = 30
13	  var logQueue = []
14	
15	  // 导入 storage（注意：需要在函数内部 require）
16	  function getStorage() {
17	    return require('@system.storage')
18	  }
19	
20	  // 保存日志到 storage
21	  function saveLogsToStorage() {
22	    try {
23	      var storage = getStorage()
24	      storage.set({
25	        key: LOG_KEY,
26	        value: JSON.stringify(logQueue.slice(0, MAX_LOGS))
