29	      console.log('日志保存失败:', e)
30	    }
31	  }
32	
33	  // 加载已有日志
34	  function loadLogsFromStorage() {
35	    try {
36	      var storage = getStorage()
37	      storage.get({
38	        key: LOG_KEY,
39	        success: function(data) {
40	          try {
41	            var saved = JSON.parse(data)
42	            if (saved && saved.length) {
43	              logQueue = saved
44	            }
45	          } catch(e) {}
46	        },
47	        fail: function() {}
48	      })
49	    } catch(e) {}
50	  }
51	
52	  // 初始化：加载已有日志
53	  loadLogsFromStorage()
54	
55	  // 手写补零（避免 padStart 的轻量运行时兼容风险——见 CC_BRIEF 已知坑 #5）
56	  function pad2(n) {
57	    return n < 10 ? '0' + n : '' + n
58	  }
59	
60	  // 添加日志
61	  var logSaveTimer = null
62	  global.addRuntimeLog = function(msg, level) {
63	    var now = new Date()
64	    var time = pad2(now.getHours()) + ':' + pad2(now.getMinutes()) + ':' + pad2(now.getSeconds())
65	
66	    logQueue.unshift({
67	      time: time,
68	      msg: msg,
