308	    toggleFavorite() {
309	      var self = this
310	
311	      if (this.eventId === undefined || this.eventId === null) {
312	        prompt.showToast({ message: '错误：事件ID无效', duration: 1000 })
313	        return
314	      }
315	
316	      var currentId = this.eventId
317	      var wasFavorited = this.isFavorited
318	
319	      var favoriteItem = {
320	        id: currentId,
321	        yearDisplay: this.yearDisplay || '未知',
322	        title: this.detailTitle || (this.keywordList && this.keywordList.length > 0 ? this.keywordList[0] : '未知事件'),
323	        region: this.displayRegion || '未知'
324	      }
325	
326	      storage.get({
327	        key: 'favorite_list',
328	        success: function(data) {
329	          var favorites = []
330	          try {
331	            favorites = JSON.parse(data) || []
332	          } catch(e) {
333	            favorites = []
334	          }
335	
336	          if (wasFavorited) {
337	            var newFavorites = []
338	            for (var i = 0; i < favorites.length; i++) {
339	              var item = favorites[i]
340	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
341	              if (itemId !== currentId) {
342	                newFavorites.push(item)
343	              }
344	            }
345	            storage.set({
346	              key: 'favorite_list',
347	              value: JSON.stringify(newFavorites),
348	              success: function() {
349	                self.isFavorited = false
350	                prompt.showToast({ message: '已取消收藏', duration: 500 })
351	                if (typeof global.addRuntimeLog === 'function') {
352	                  global.addRuntimeLog('取消收藏成功: ID=' + currentId, 'info')
