356	                prompt.showToast({ message: '取消收藏失败', duration: 500 })
357	              }
358	            })
359	          } else {
360	            var exists = false
361	            for (var i = 0; i < favorites.length; i++) {
362	              var item = favorites[i]
363	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
364	              if (itemId === currentId) {
365	                exists = true
366	                break
