391	            var favorites = [favoriteItem]
392	            storage.set({
393	              key: 'favorite_list',
394	              value: JSON.stringify(favorites),
395	              success: function() {
396	                self.isFavorited = true
397	                prompt.showToast({ message: '已添加收藏', duration: 500 })
398	              }
399	            })
400	          }
401	        }
402	      })
