242	
243	  function pad2(n) { return n < 10 ? '0' + n : '' + n }
244	
245	  export default {
246	    private: {
247	      time: '00:00',
248	      dsId: 0,
249	      dsName: '',
250	      dsDesc: '',
251	      dsIcon: '',
252	      dsIconClass: 'ds-icon-box ci-ds',
253	      dsTags: [],
254	      dsCount: -1,
255	      isNotPill: false,
256	      activeTag: null,
257	      showRectTitle: false,
258	      showAppTitle: true,
259	      screentype: 'rect',
260	      // 搜索态（v1.16.72 页内搜索，逻辑按主界面简化）
261	      searchQuery: '',
262	      searchActive: false,
263	      showKeyboard: false,
264	      displayList: [],
265	      visibleCount: 5,
266	      moreText: '',
267	      totalCount: 0,
268	      searched: false,
269	      searchError: false,
270	      loading: false,
271	      currentPage: 1,
272	      pageSize: 20,
273	      allLoaded: false,
274	      searchSeq: 0,
275	      // 语音态
276	      voiceActive: false,
277	      voiceText: '聆听中…',
278	      voiceTimer: null,
279	      timeTimer: null,
280	      isDestroyed: false
281	    },
282	
283	    computed: {
284	      displayQuery() {
285	        return this.searchQuery
286	      },
287	      searchBoxClass() {
288	        // 审查低#10：模板已写固定基类 search-box，这里只返回修饰类
289	        var c = ''
290	        if (this.voiceActive) c = 'searchbox-voice'
291	        if (this.searchQuery) c += ' searchbox-typed'
292	        return c
293	      },
294	      // 渐进显示：模板禁表达式，切片在此（曾漏写导致有结果的场景渲染空白——实测抓出）
295	      visibleList() {
296	        var n = this.visibleCount || 5
297	        return this.displayList.slice(0, n)
298	      }
299	    },
300	
301	    onInit() {
302	      var target = (typeof global !== 'undefined') ? global.dsViewTarget : null
303	      // ⚠️ 审查中#3：onInit 阶段 DomPage 未 ready，router.back() 静默无效（项目已知坑）
304	      // ——此处只记无效标志，onShow 再执行返回
305	      this._invalidTarget = (!target && target !== 0)
306	      if (this._invalidTarget) return
307	      this.dsId = target
308	      var info = (typeof global.getDatasetInfo === 'function') ? global.getDatasetInfo(target) : null
309	      if (!info) { this._invalidTarget = true; return }
310	      this.dsName = info.name
311	      this.dsDesc = info.desc || ''
312	      this.dsIcon = info.icon
313	      this.dsIconClass = 'ds-icon-box ' + (info.colorClass || 'ci-ds')
314	      this.dsCount = (info.count !== undefined) ? info.count : -1
315	      var tags = []
316	      for (var i = 0; i < info.tags.length; i++) {
317	        tags.push({ label: info.tags[i].label, value: info.tags[i].value, cls: 'ds-tag' })
318	      }
319	      this.dsTags = tags
320	      // 屏幕形态（键盘组件所需）
321	      var self = this
322	        device.getInfo({
323	          success: function(data) {
324	            var shape = data.screenShape
325	            self.screentype = shape === 'circle' ? 'circle' : (shape === 'pill-shaped' ? 'pill-shaped' : 'rect')
326	            self.showAppTitle = (shape === 'pill-shaped') || (shape === 'circle')
327	            self.showRectTitle = !self.showAppTitle
328	            // 条数信息仅 PRO 方屏/圆屏展示（胶囊屏主人定案不改）
329	            self.isNotPill = (shape !== 'pill-shaped')
330	          },
331	          fail: function() {}
332	        })
333	    },
334	
335	    onShow() {
336	      var self = this
337	      // 审查中#3：onInit 记录的无效目标在这里退（onInit 阶段 router 静默失效）
338	      if (this._invalidTarget) { router.back(); return }
339	      // 审查中#4：onShow 每次都 new interval 会泄漏（从详情页返回一次多一个）——先清旧的
340	      if (this.timeTimer) { clearInterval(this.timeTimer); this.timeTimer = null }
341	      this.updateTime()
342	      this.timeTimer = setInterval(function() { self.updateTime() }, 30000)
343	    },
344	
345	    onDestroy() {
346	      this.isDestroyed = true
347	      if (this.timeTimer) { clearInterval(this.timeTimer); this.timeTimer = null }
348	      if (this.voiceTimer) { clearInterval(this.voiceTimer); this.voiceTimer = null }
349	      this.searchSeq++
350	    },
351	
352	    updateTime() {
353	      var now = new Date()
354	      this.time = pad2(now.getHours()) + ':' + pad2(now.getMinutes())
355	    },
356	
357	    // ===== 标签筛选（选中后再搜索只用该标签） =====
358	    pickTag(tag) {
359	      var same = (this.activeTag === tag.value)
360	      this.activeTag = same ? null : tag.value
361	      var tags = []
362	      var src = this.dsTags
363	      for (var i = 0; i < src.length; i++) {
364	        var on = (src[i].value === this.activeTag)
365	        tags.push({ label: src[i].label, value: src[i].value, cls: on ? 'ds-tag ds-tag-on' : 'ds-tag' })
366	      }
367	      this.dsTags = tags
368	      // 已有词则立即按新范围重搜
369	      if (this.searchQuery && this.searchQuery.trim()) {
370	        this.searchActive = true
371	        this.resetAndSearch()
372	      }
373	    },
374	
375	    // ===== 搜索框交互（同主界面简化版） =====
376	    toggleSearchBox() {
377	      if (this.voiceActive) return
378	      if (this.showKeyboard) {
379	        this.showKeyboard = false
380	        this.finishInput()
381	      } else {
382	        this.searchActive = true
383	        this.openKeyboard()
384	      }
385	    },
386	
387	    openKeyboard() {
388	      var self = this
389	      // v1.16.81：150→60ms——延迟只为让搜索态先落一帧；键盘组件已是 if 按需创建，
390	      // 150ms 让主人感知到「点搜索栏有延迟」（实测反馈）
391	      setTimeout(function() { if (!self.isDestroyed) self.showKeyboard = true }, 60)
392	    },
393	
394	    onInput(evt) {
395	      var content = evt.detail.content
396	      if (content === undefined || content === null) return
397	      this.searchQuery += content
398	    },
399	
400	    onDelete() {
401	      this.searchQuery = this.searchQuery.slice(0, -1)
402	    },
403	
404	    clearSearch() {
405	      this.searchQuery = ''
406	      this.searchSeq++
407	      this.displayList = []
408	      this.searched = false
409	      this.loading = false
410	    },
411	
412	    // 收键盘 → 搜索（页内限定该集 + 标签）
413	    finishInput() {
414	      this.showKeyboard = false
415	      if (!this.searchQuery || !this.searchQuery.trim()) {
416	        // 空词收键盘：回资料信息态
417	        this.searchActive = false
418	        return
419	      }
420	      this.resetAndSearch()
421	    },
422	
423	    resetAndSearch() {
424	      this.currentPage = 1
425	      this.allLoaded = false
426	      this.searched = true
427	      this.searchError = false
428	      this.loading = true
429	      this.displayList = []
430	      this.visibleCount = 5
431	      this.loadPage(1, true)
432	    },
433	
434	    async loadPage(page, force) {
435	      if (!force && (this.loading || this.allLoaded)) return
436	      var q = this.searchQuery.trim()
437	      if (!q) return
438	      this.loading = true
439	      var seq = ++this.searchSeq
440	      var self = this
441	      try {
442	        var result = await global.searchHistory(q, {
443	          datasetId: this.dsId,
444	          region: this.activeTag || 'all',
445	          page: page,
446	          pageSize: this.pageSize
447	        })
448	        if (seq !== this.searchSeq || this.isDestroyed) return
449	        var items = (result && result.results) || []
450	        var formatted = items.map(function(item) {
451	          var title = item.title || '未知条目'
452	          if (title.indexOf(',') !== -1) title = title.split(',')[0].trim()
453	          return {
454	            id: (item.globalId !== undefined ? item.globalId : item.id),   // 跨集全局 id（详情页 decodeGlobalId 需要）
455	            yearDisplay: item.yearDisplay || item.region || self.dsName,
456	            title: title,
457	            region: item.region || self.dsName,
458	            yearClass: 'result-year',
459	            titleClass: 'result-title',
460	            catClass: 'result-region'
461	          }
462	        })
463	        if (page === 1) {
464	          this.displayList = formatted
465	        } else {
466	          this.displayList = this.displayList.concat(formatted)
467	        }
468	        this.currentPage = page
469	        this.loading = false
470	        // 结果总数（引擎权威 total；缺失时退化为本地 list 长度）
471	        this.totalCount = result.total || this.displayList.length
472	        var more = this.displayList.length - (this.visibleCount || 5)
473	        this.moreText = more > 0 ? ('显示更多（还有 ' + more + ' 条）') : ''
474	        if (result && result.allLoaded) this.allLoaded = true
475	      } catch (e) {
476	        if (seq !== this.searchSeq || this.isDestroyed) return
477	        this.loading = false
478	        // 审查低#12：读文件回调丢失等异常 ≠ 无结果——显示错误提示（可重试）
479	        this.searched = true
480	        this.searchError = true
481	      }
482	    },
483	
484	    showMore() {
485	      this.visibleCount = (this.visibleCount || 5) + 5
486	      var more = this.displayList.length - this.visibleCount
487	      this.moreText = more > 0 ? ('显示更多（还有 ' + more + ' 条）') : ''
488	      if (this.visibleCount >= this.displayList.length && !this.allLoaded && !this.loading) {
489	        this.loadPage(this.currentPage + 1)
490	      }
491	    },
492	
493	    gotoDetail(id) {
494	      if (this.showKeyboard) return
495	      global.selectedEventId = id
496	      router.push({ uri: '/pages/detail' })
497	    },
498	
499	    // ===== 语音搜索（保留；AI 搜索仅主界面） =====
500	    startVoiceSearch() {
501	      if (this.voiceActive) return
502	      this.voiceActive = true
503	      this.voiceText = '聆听中…'
504	      var self = this
505	      // 超时兜底：12s 未识别自动退出（审查低#11：补 cancel + 提示文案）
506	      this.voiceTimer = setTimeout(function() {
507	        if (self && !self.isDestroyed && self.voiceActive) {
508	          self.voiceActive = false
509	          self.voiceText = '识别超时，请重试'
510	          getAssistant().cancel()
511	        }
512	      }, 12000)
513	      getAssistant().recognize(function(r) {
514	        if (self.isDestroyed || !self.voiceActive) return
515	        if (self.voiceTimer) { clearTimeout(self.voiceTimer); self.voiceTimer = null }
516	        self.voiceActive = false
517	        if (r && r.ok && r.text) {
518	          self.searchQuery = r.text
519	          self.searchActive = true
520	          self.resetAndSearch()
521	        }
522	      })
523	    },
524	
525	    exitVoiceSearch() {
526	      this.voiceActive = false
