67	<script>
68	  import { getTransferState } from '../../SearchEngine/BtTransfer.js'
69	  import router from '@system.router'
70	
71	  function pad2(n) { return n < 10 ? '0' + n : '' + n }
72	
73	  export default {
74	    private: {
75	      time: '00:00',
76	      statusText: '等待资料…',
77	      dsName: '',
78	      progressPercent: 0,
79	      percentText: '0%',
80	      detailText: '',
81	      isError: false,
82	      timer: null,
83	      timeTimer: null,
84	      navigated: false
85	    },
86	
87	    onShow() {
88	      var self = this
89	      this.updateTime()
90	      this.timeTimer = setInterval(function() { self.updateTime() }, 30000)
91	      // 轮询传输状态（300ms）：进度/完成/失败驱动 UI 与跳转
92	      this.timer = setInterval(function() { self.poll() }, 300)
93	      this.poll()
94	    },
95	
96	    onDestroy() {
97	      if (this.timer) { clearInterval(this.timer); this.timer = null }
98	      if (this.timeTimer) { clearInterval(this.timeTimer); this.timeTimer = null }
99	    },
100	
101	    updateTime() {
102	      var now = new Date()
103	      this.time = pad2(now.getHours()) + ':' + pad2(now.getMinutes())
104	    },
105	
106	    // 状态 → UI；done 由本页跳 loading 建缓存（传输页职责内聚，BtTransfer 只维护状态）
107	    poll() {
108	      if (this.navigated) return
109	      var st = getTransferState()
110	      this.dsName = st.name || st.ds || ''
111	      this.isError = st.phase === 'error'
112	      if (st.phase === 'receiving') {
113	        this.statusText = '正在接收资料…'
114	        var p = st.total > 0 ? Math.round(st.done / st.total * 100) : 0
115	        this.progressPercent = p
116	        this.percentText = p + '%'
117	        this.detailText = st.total > 0
118	          ? ('已完成 ' + st.done + '/' + st.total + ' 个文件' + (st.currentFile ? '（' + st.currentFile + '）' : ''))
119	          : '正在连接…'
120	      } else if (st.phase === 'saving') {
121	        this.statusText = '正在保存资料…'
122	        this.progressPercent = 100
123	        this.percentText = '100%'
124	        this.detailText = '校验通过，正在写入存储'
125	      } else if (st.phase === 'done') {
126	        this.statusText = '传输完成'
127	        this.progressPercent = 100
128	        this.percentText = '100%'
129	        this.detailText = '正在建立索引缓存…'
130	        this.navigated = true
131	        // 只给传输来的这个集建缓存（loading 单集模式）
132	        router.replace({ uri: '/pages/loading', params: { source: 'bt', dsId: st.dsId } })
133	      } else if (st.phase === 'error') {
134	        this.statusText = '接收失败'
135	        this.detailText = st.error || ''
136	      } else if (st.phase === 'aborted') {
137	        this.statusText = '已停止'
138	        this.detailText = '手机端已停止传输'
139	      } else {
140	        this.statusText = '等待资料…'
141	        this.detailText = '正在连接中'
142	      }
143	    },
144	
145	    // 吞掉滑动（传输中不允许退出——唯一退出途径：手机端停止 / 传输完毕）
146	    noop() {}
147	  }
148	</script>
