60	<script>
61	  import router from '@system.router'
62	  import prompt from '@system.prompt'
63	  import storage from '@system.storage'
64	
65	  export default {
66	    private: {
67	      favorites: [],
68	      loading: true
69	    },
70	
71	    // onShow 每次回到本页都刷新，保证详情页收藏/取消后列表同步
72	    onShow() {
73	      this.refreshFavorites()
74	    },
75	
76	    // 读取收藏列表：兼容旧数据里纯数字元素，统一转成对象格式（只读不写回，storage 原格式保持不变）
77	    refreshFavorites() {
78	      var self = this
79	      storage.get({
80	        key: 'favorite_list',
81	        success: function(data) {
82	          var list = []
83	          try {
84	            list = JSON.parse(data) || []
85	          } catch(e) {
86	            list = []
87	          }
88	          var normalized = list.map(function(item) {
89	            if (typeof item === 'number') {
90	              return { id: item, title: '事件 #' + item, yearDisplay: '', region: '' }
91	            }
92	            return {
93	              id: item.id || 0,
94	              title: item.title || '未知事件',
95	              yearDisplay: item.yearDisplay || '',
96	              region: item.region || ''
97	            }
98	          })
99	          self.favorites = normalized
100	          self.loading = false
101	        },
102	        fail: function() {
103	          self.favorites = []
104	          self.loading = false
105	        }
106	      })
107	    },
108	
109	    // 点击条目进入详情页（与 result.ux/index.ux 一致：先写 global.selectedEventId 再跳转）
110	    gotoDetail(id) {
111	      if (id === undefined || id === null) return
112	      if (this.$app.$def.isNavigating) return
113	      global.selectedEventId = id
114	      if (typeof global.addRuntimeLog === 'function') {
115	        global.addRuntimeLog('从收藏打开详情: ID=' + id, 'info')
116	      }
117	      router.push({ uri: '/pages/detail', params: { id: id } })
118	    },
119	
120	    // 移除收藏：按 id 从数组剔除并写回 storage（self 写法避免回调内 this 依赖）
121	    removeFavorite(id) {
122	      var self = this
123	      var idx = -1
124	      for (var i = 0; i < this.favorites.length; i++) {
125	        if (this.favorites[i].id === id) {
126	          idx = i
127	          break
128	        }
129	      }
130	      if (idx === -1) return
131	      var newFavorites = []
132	      for (var j = 0; j < this.favorites.length; j++) {
133	        if (j !== idx) {
134	          newFavorites.push(this.favorites[j])
135	        }
136	      }
137	      self.favorites = newFavorites
138	      storage.set({
139	        key: 'favorite_list',
140	        value: JSON.stringify(newFavorites),
141	        success: function() {
142	          prompt.showToast({ message: '已移除收藏', duration: 500 })
143	          global.addRuntimeLog && global.addRuntimeLog('移除收藏: ID=' + id, 'info')
144	        },
145	        fail: function() {
146	          prompt.showToast({ message: '移除收藏失败', duration: 500 })
147	        }
148	      })
149	    },
150	
151	    // 右滑返回
152	    onSwipe(eve) { if (eve.direction === 'right') { router.back() } },
153	
154	    goBack() { router.back() }
155	  }
156	</script>
